#ifndef CGTEST_H
#define CGTEST_H

/* Generated by "cgtest --create". Test functions have the form
 * "void test_<name>(void) { ... }" - a plain "void" keeps test
 * files C89-portable (no <stdbool.h>). EXPECT_* macros report a
 * failed check and keep running the test; ASSERT_* macros report
 * it and return immediately - use ASSERT for a precondition the
 * rest of the function depends on (e.g. a NULL check before a
 * dereference), EXPECT otherwise. */

#include <stdio.h>

/* The generated runner reads this after calling each test to
 * decide pass/fail, resetting it to 0 first. */
extern int cgtest_failed;

#define EXPECT_TRUE(cond) \
    do { \
        if (!(cond)) { \
            fprintf(stderr, "  FAIL %s:%d: EXPECT_TRUE(%s)\n", __FILE__, __LINE__, #cond); \
            cgtest_failed = 1; \
        } \
    } while (0)

#define EXPECT_FALSE(cond) \
    do { \
        if (cond) { \
            fprintf(stderr, "  FAIL %s:%d: EXPECT_FALSE(%s)\n", __FILE__, __LINE__, #cond); \
            cgtest_failed = 1; \
        } \
    } while (0)

#define ASSERT_TRUE(cond) \
    do { \
        if (!(cond)) { \
            fprintf(stderr, "  FAIL %s:%d: ASSERT_TRUE(%s)\n", __FILE__, __LINE__, #cond); \
            cgtest_failed = 1; \
            return; \
        } \
    } while (0)

#define ASSERT_FALSE(cond) \
    do { \
        if (cond) { \
            fprintf(stderr, "  FAIL %s:%d: ASSERT_FALSE(%s)\n", __FILE__, __LINE__, #cond); \
            cgtest_failed = 1; \
            return; \
        } \
    } while (0)

#endif /* CGTEST_H */
